print("LOOP LIST")
LISTs=["APPLE","ORANGE","KIWI"]
for x in LISTs:#Take each element from the LISTs list, one at a time, and temporarily store it in x.
  print(x)# to print the items in lists.
"""
Here:
LISTs = list
x = temporary variable
for = keyword
in = tells Python to take values from the list
"""

number=[10,20,30,40,50]
total=0
for num in number:
  total=total+num
print(total)